Out out_build( Out_Func out_func , UInt8 sizeof_out )
{
    Out out_obj       = (Out)os_mem_request( sizeof_out ) ; 

    out_obj->out_func = out_func  ;

    out_obj->state    = NULL ; 

    return out_obj ; 
}

